import manifest from '../../manifest';
import { bookingHeaders } from './integrations/booking-com';

chrome.runtime.onInstalled.addListener(async (details) => {
  const version = chrome.runtime.getManifest().version;
  console.log(version, details.previousVersion, details.reason);
  if (
    details.reason === 'update' &&
    details.previousVersion !== manifest.version
  ) {
    await chrome.storage.local.clear();
    console.log(`Updated from ${details.previousVersion} to ${version}!`);
  }

  const rules = [
    {
      id: 1,
      action: {
        type: 'modifyHeaders',
        requestHeaders: [
          {
            header: 'Referer',
            operation: 'set',
            value: bookingHeaders.Referer,
          },
        ],
      },
      condition: {
        regexFilter: '^https://admin.booking.com/dml/graphql.json(.*)',
        resourceTypes: ['xmlhttprequest'],
      },
    },
  ];

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: rules.map((r) => r.id),
    addRules: rules as any,
  });
});
