import { changeState, clearState, getState, inactiveState } from '../store';
import { evaluateOnTab } from '../utils';
import Cookie = chrome.cookies.Cookie;

// AccessToken helpers
function isTokenExpired(token?: string) {
  if (!token) return true;
  const expiry = JSON.parse(atob(token.split('.')[1])).exp;
  // biome-ignore lint/complexity/useDateNow: <explanation>
  return Math.floor(new Date().getTime() / 1000) >= expiry;
}

async function hasSessionToLogIn() {
  const cookies: Cookie[] = await new Promise((resolve) =>
    chrome.cookies.getAll({}, (_cookies: Cookie[]) =>
      resolve(_cookies.filter((cookie: Cookie) => isPlatform(cookie.domain)))
    )
  );

  const sessions = cookies.filter(
    (e) => e.name === '__session' || e.name === '__client'
  );

  return sessions.length >= 2;
}

export function isPlatform(url?: string) {
  if (!url) return false;
  return url.includes('vrplatform.app') || url.includes('finalytic.io');
}

export async function syncLogin(tabId?: number) {
  console.log(`Platform sync login on ${tabId}`);
  if (!tabId) return;

  if (await hasSessionToLogIn()) {
    return;
  }

  await inactiveState(tabId);
  return await clearState();
}

export async function platformAuth(tabId?: number) {
  console.log(`Platform auth on ${tabId}`);
  if (!tabId) return;

  const userEval = await evaluateOnTab(tabId, () => {
    return {
      userId: localStorage.getItem('uid') || undefined,
    };
  });

  const state = await getState();
  if (!userEval || !userEval.userId) {
    console.log('No user found on website');
    return;
  }

  if (
    state.userId &&
    state.userId === userEval.userId &&
    state.accessToken &&
    !isTokenExpired(state.accessToken)
  ) {
    console.log(
      'Skip auth refresh because user didnt change and auth still valid'
    );
    return;
  }

  if (!(await hasSessionToLogIn())) {
    return;
  }

  const platformData = await evaluateOnTab(tabId, () => {
    return {
      accessToken: localStorage.getItem('at') || undefined,
      teamId: localStorage.getItem('tid') || undefined,
    };
  });

  if (!platformData || !platformData.accessToken) {
    console.log('No access token found');
    return;
  } else if (isTokenExpired(platformData.accessToken)) {
    console.log('Website at is expired');
    return;
  }

  console.log('Setting state', platformData);

  return changeState({
    accessToken: platformData.accessToken,
    teamId: platformData.teamId,
    userId: userEval.userId,
  });
}
