import { getIntegration } from './integrations';
import { getSession } from './services';
import { changeState, getState, inactiveState } from './store';
import { type Account, type Integration, Status } from './types';
import { displayBadge, statusToBadge } from './utils';

chrome.storage.onChanged.addListener(async (changes) => {
  if ('status' in changes) {
    console.log('Changing badge');
    await displayBadge(statusToBadge(changes.status.newValue));
  }

  if (!('status' in changes) && !('integration' in changes)) return;

  const { integration, tabId, status } = await getState();

  console.log(`${integration} changed to ${status}`);

  if (integration && tabId && status === Status.NOT_SIGNED_IN) {
    await inactiveState(tabId);
  }

  if (integration && tabId && status === Status.SIGNED_IN) {
    const session = await getSession(tabId);

    if (!session) {
      return;
    }

    const { retrieveAccount } = getIntegration(integration) as Integration;

    let account: Account | undefined;
    if (retrieveAccount) {
      account = await retrieveAccount(tabId, session);

      if (!account?.email) {
        return;
      }
    }

    const { status: newStatusSinceRequest } = await getState();

    // Happening when request take too long and
    // user change tab, it will override storage
    if (newStatusSinceRequest !== status) {
      return;
    }

    console.log('Account', account);
    console.log('Session', session);

    await changeState({
      session,
      account,
    });
  }
});
