import { services } from './integrations';
import { changeState, getState, inactiveState } from './store';
import Tab = chrome.tabs.Tab;
import { disableBadge } from './utils';

export async function handler(tab: Tab | undefined) {
  if (!tab) {
    return;
  }
  console.log(`Changing tab id: ${tab.url}`);

  const foundIntegration = tab?.url
    ? services.find((e) => tab.url?.includes(e.matchUrl))?.displayName
    : undefined;

  const state = await getState();

  if (
    foundIntegration &&
    state.integration?.length &&
    state.integration !== foundIntegration
  ) {
    await inactiveState(tab?.id);
  }

  if (foundIntegration) {
    console.log('Found integration', foundIntegration);
    await changeState({
      tabId: tab.id,
      integration: foundIntegration,
    });
  } else {
    await chrome.storage.local.remove(['integration']);
    await disableBadge();
  }
}
chrome.tabs.onActivated.addListener(async ({ tabId }) => {
  if (!tabId) return;
  const tab = await chrome.tabs.get(tabId);

  return handler(tab);
});
chrome.tabs.getCurrent().then((tab) => {
  if (tab) return handler(tab);
});
