import type { Badge, Status } from '../types';

export const statusToBadge = (status: Status): Badge => {
  switch (status) {
    case 'SIGNED_IN':
      return { text: '✓', color: '#00ff32' };
    case 'SIGNING_IN':
      return { text: '...', color: '#00acff' };
    case 'NOT_SIGNED_IN':
      return { text: '✗', color: '#ff0000' };
    default:
      return { text: '', color: '#00acff' };
  }
};
