import manifest from '../../manifest';
import { getIntegration } from './integrations';
import type { Integration } from './types';

const HOST_PERMISSIONS = manifest.host_permissions?.map(
  (e) => `${e}*`
) as string[];

console.log('HOST_PERMISSIONS', HOST_PERMISSIONS);

const getIntegrationFromRequestInitiator = (
  initiator: string
): Integration | undefined => {
  const parsedURL = new URL(initiator);
  const hosts = parsedURL.host.split('.');
  let integration: string | undefined;

  if (hosts.length >= 3) {
    integration = hosts[1];
  } else if (hosts.length === 2) {
    integration = hosts[0];
  }

  if (!integration) {
    return;
  }

  return getIntegration(integration);
};

chrome.webRequest.onBeforeRequest.addListener(
  (webRequest) => {
    const { url, method, requestBody, initiator } = webRequest;

    if (!initiator) {
      return;
    }

    if (
      method === 'GET' ||
      !requestBody ||
      !requestBody.raw ||
      requestBody.raw.length === 0
    ) {
      return;
    }
    const integration = getIntegrationFromRequestInitiator(initiator);

    if (!integration || !integration.onNetworkEvent) {
      return;
    }

    const bytes = requestBody.raw[0].bytes;

    if (!bytes) {
      return;
    }

    const body = new TextDecoder('utf-8').decode(bytes);

    try {
      const parsedBody = JSON.parse(body);
      integration.onNetworkEvent({
        method,
        initiator,
        url,
        body: parsedBody,
      });
    } catch (_e) {}
  },
  {
    urls: HOST_PERMISSIONS,
  },
  ['requestBody']
);

chrome.webRequest.onCompleted.addListener(
  (webResponse) => {
    const { url, method, statusCode, initiator } = webResponse;

    if (!initiator) {
      return;
    }

    if (statusCode !== 200 || method !== 'GET') {
      return;
    }

    const integration = getIntegrationFromRequestInitiator(initiator);

    if (!integration || !integration.onNetworkEventCompleted) {
      return;
    }

    integration.onNetworkEventCompleted({
      method,
      initiator,
      url,
      statusCode,
    });
  },
  { urls: HOST_PERMISSIONS }
);
