import { changeState, getState } from '../store';
import { evaluateOnTab } from '../utils';

export async function syncTeam(tabId?: number) {
  console.log(`Platform sync team on ${tabId}`);
  if (!tabId) return;

  const platformData = await evaluateOnTab(tabId, () => ({
    teamId: localStorage.getItem('tid') || undefined,
  }));

  const { teamId } = await getState();
  console.log('steam', teamId, platformData, teamId === platformData?.teamId);

  if (teamId === platformData?.teamId) {
    console.log('Skip team sync because team didnt change');
    return;
  }

  console.log('Setting team state', platformData);
  return changeState({
    teamId: platformData?.teamId || teamId,
  });
}
