chrome.runtime.onMessageExternal.addListener(
  (request, sender, sendResponse) => {
    const popup_url = 'src/pages/popup/index.html';
    const { data } = request;
    const { message } = data;

    const allowed_origins = ['localhost', 'finalytic.io', 'vrplatform.app'];

    if (
      !allowed_origins.some((origin) => (sender.origin || '').includes(origin))
    )
      return sendResponse({ exists: true, message: 'Origin not allowed.' });

    if (message === 'redirect' && data.redirect_url) {
      const { appId, connectionId, redirect_url } = data;

      sendResponse({ exists: true });

      // Open app url in new tab
      chrome.tabs.create({ url: redirect_url });

      // Open popup but in a new tab
      // chrome.tabs.create({ url: popup_url });

      // Opens popup in new window
      setTimeout(() => {
        if (appId && !connectionId)
          chrome.storage.local.set({ appId, view: 'connect-view' });
        if (connectionId)
          chrome.storage.local.set({ connectionId, view: 'connect-view' });

        chrome.system.display.getInfo({ singleUnified: true }, (info) => {
          const wDimension = info[0].workArea;
          const { top, left, height, width } = wDimension;
          console.log(top);
          const w = 500;
          const h = 400;
          const l = width - width / 5 - w / 2 + left;
          const t = height - h * 2 + top;
          const newWindow = () => {
            console.log('in new window');
          };
          chrome.windows.create(
            {
              url: popup_url,
              type: 'popup',
              width: w,
              height: h,
              left: Math.round(l),
              top: Math.round(t),
            },
            newWindow
          );
        });
      }, 1000);
    }

    if (message === 'team_changed') {
      if (!data.teamId)
        return sendResponse({ exists: true, message: 'Missing team id.' });

      chrome.storage.local.set({ teamId: data.teamId });
      sendResponse({ exists: true, message: 'Team id was set.' });
    }

    if (message === 'token') {
      if (data.token) chrome.storage.local.set({ accessToken: data.token });
      else chrome.storage.local.remove('accessToken');
      sendResponse({ exists: true, message: 'Received token.' });
    }
  }
);
