import { getIntegration } from './integrations';
import { handler } from './on-tab-activated';
import { getSession, syncLogin } from './services';
import { isPlatform, platformAuth } from './services';
import { syncTeam } from './services/platform-team';
import { changeState, getState, inactiveState } from './store';
import { type Integration, Status } from './types';
import { displayBadge, statusToBadge } from './utils';

const intervalFn = async () => {
  try {
    const [currentTab] = await chrome.tabs.query({
      active: true,
      lastFocusedWindow: true,
    });
    console.log(isPlatform(currentTab?.url));
    if (isPlatform(currentTab?.url)) {
      await Promise.all([
        await syncLogin(currentTab?.id),
        await syncTeam(currentTab?.id),
        await platformAuth(currentTab?.id),
      ]);
    } else {
      let state = await getState();

      if (!state.integration || !state.tabId) {
        await handler(currentTab);

        // refresh state
        state = await getState();
      }

      const { integration, tabId, status, account } = state;

      console.log(integration, tabId, status, account);

      if (integration && tabId) {
        if (status) {
          await displayBadge(statusToBadge(status));
        }

        if (status === Status.NOT_SIGNED_IN && !account?.displayName) {
          await inactiveState(tabId);
        }

        const session = await getSession(tabId);
        const { checkCurrentStatus, checkCredentials } = getIntegration(
          integration
        ) as Integration;

        const _status = await checkCurrentStatus(tabId, session);

        console.log('Current status', _status, currentTab);
        if (_status === Status.SIGNING_IN && checkCredentials) {
          await checkCredentials(tabId);
        }

        if (status !== _status) await changeState({ status: _status });
      }
    }
  } catch (error) {
    console.log(error);
  }
  setTimeout(intervalFn, 1000);
};

intervalFn();
